// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *BOMComponent) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *BOMComponent) Get(primaryKey interface{}) bool {
	// Handle composite primary key (map[string]interface{})
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		var parent_item_noVal types.Code
		if v, exists := pkMap["parent_item_no"]; exists {
			switch val := v.(type) {
			case types.Code:
				parent_item_noVal = val
			case string:
				parent_item_noVal = types.NewCode(val)
			}
		}
		var line_noVal int
		if v, exists := pkMap["line_no"]; exists {
			switch val := v.(type) {
			case int:
				line_noVal = val
			case float64:
				line_noVal = int(val)
			case string:
				// the key part as text: the API's "CUSTOMER1,10000"
				if n, err := strconv.Atoi(strings.TrimSpace(val)); err == nil {
					line_noVal = n
				}
			}
		}
		return t.GetByPK(parent_item_noVal, line_noVal)
	}
	// For tables with composite keys, direct value is not supported
	// Use a map[string]interface{} with field names as keys

	fmt.Printf("Error: Invalid primary key type for BOM_Component.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *BOMComponent) GetByPK(parent_item_no types.Code, line_no int) bool {
	tableName := fmt.Sprintf("%s$%s", t.company, BOMComponentTableName)
	var parent_item_noNull sql.NullString
	var line_noVal int
	var type_Int int
	var noNull sql.NullString
	var bill_of_materialsBool sql.NullBool
	var descriptionNull sql.NullString
	var unit_of_measure_codeNull sql.NullString
	var quantity_perNull sql.NullString
	var positionNull sql.NullString
	var position_2Null sql.NullString
	var position_3Null sql.NullString
	var machine_noNull sql.NullString
	var production_lead_timeVal int
	var variant_codeNull sql.NullString

	// Collect arguments for query
	args := []interface{}{
		parent_item_no,
		line_no,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT parent_item_no, line_no, type, no, bill_of_materials, description, unit_of_measure_code, quantity_per, position, position_2, position_3, machine_no, production_lead_time, variant_code FROM "%s" WHERE 1=1 AND parent_item_no = ? AND line_no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&parent_item_noNull,
		&line_noVal,
		&type_Int,
		&noNull,
		&bill_of_materialsBool,
		&descriptionNull,
		&unit_of_measure_codeNull,
		&quantity_perNull,
		&positionNull,
		&position_2Null,
		&position_3Null,
		&machine_noNull,
		&production_lead_timeVal,
		&variant_codeNull,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get BOM_Component: %v\n", err)
		return false
	}

	// Populate fields
	t.Parent_item_no = types.NewCode(parent_item_noNull.String)
	t.Line_no = line_noVal
	t.Type = BOMComponentType(type_Int)
	t.No = types.NewCode(noNull.String)
	t.Bill_of_materials = bill_of_materialsBool.Bool
	t.Description = types.NewText(descriptionNull.String)
	t.Unit_of_measure_code = types.NewCode(unit_of_measure_codeNull.String)
	t.Quantity_per, _ = types.NewDecimalFromString(quantity_perNull.String)
	t.Position = types.NewCode(positionNull.String)
	t.Position_2 = types.NewCode(position_2Null.String)
	t.Position_3 = types.NewCode(position_3Null.String)
	t.Machine_no = types.NewCode(machine_noNull.String)
	t.Production_lead_time = production_lead_timeVal
	t.Variant_code = types.NewCode(variant_codeNull.String)

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

// Insert inserts the record into the database
func (t *BOMComponent) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, BOMComponentTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Parent_item_no,
		t.Line_no,
		t.Type,
		t.No,
		t.Bill_of_materials,
		t.Description,
		t.Unit_of_measure_code,
		t.Quantity_per,
		t.Position,
		t.Position_2,
		t.Position_3,
		t.Machine_no,
		t.Production_lead_time,
		t.Variant_code,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (parent_item_no, line_no, type, no, bill_of_materials, description, unit_of_measure_code, quantity_per, position, position_2, position_3, machine_no, production_lead_time, variant_code) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (parent_item_no, line_no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert BOM_Component: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(BOMComponentTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *BOMComponent) InsertAll(records []*BOMComponent, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Parent_item_no,
			r.Line_no,
			r.Type,
			r.No,
			r.Bill_of_materials,
			r.Description,
			r.Unit_of_measure_code,
			r.Quantity_per,
			r.Position,
			r.Position_2,
			r.Position_3,
			r.Machine_no,
			r.Production_lead_time,
			r.Variant_code,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, BOMComponentTableName)
	columns := []string{"parent_item_no", "line_no", "type", "no", "bill_of_materials", "description", "unit_of_measure_code", "quantity_per", "position", "position_2", "position_3", "machine_no", "production_lead_time", "variant_code"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *BOMComponent) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("parent_item_no") {
			keyChanged = true
		}
		if t.hasFieldChanged("line_no") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, BOMComponentTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("parent_item_no") {
			setClauses = append(setClauses, "parent_item_no = ?")
			values = append(values, t.Parent_item_no)
		}
		if t.hasFieldChanged("line_no") {
			setClauses = append(setClauses, "line_no = ?")
			values = append(values, t.Line_no)
		}
		if t.hasFieldChanged("type") {
			setClauses = append(setClauses, "type = ?")
			values = append(values, t.Type)
		}
		if t.hasFieldChanged("no") {
			setClauses = append(setClauses, "no = ?")
			values = append(values, t.No)
		}
		if t.hasFieldChanged("bill_of_materials") {
			setClauses = append(setClauses, "bill_of_materials = ?")
			values = append(values, t.Bill_of_materials)
		}
		if t.hasFieldChanged("description") {
			setClauses = append(setClauses, "description = ?")
			values = append(values, t.Description)
		}
		if t.hasFieldChanged("unit_of_measure_code") {
			setClauses = append(setClauses, "unit_of_measure_code = ?")
			values = append(values, t.Unit_of_measure_code)
		}
		if t.hasFieldChanged("quantity_per") {
			setClauses = append(setClauses, "quantity_per = ?")
			values = append(values, t.Quantity_per)
		}
		if t.hasFieldChanged("position") {
			setClauses = append(setClauses, "position = ?")
			values = append(values, t.Position)
		}
		if t.hasFieldChanged("position_2") {
			setClauses = append(setClauses, "position_2 = ?")
			values = append(values, t.Position_2)
		}
		if t.hasFieldChanged("position_3") {
			setClauses = append(setClauses, "position_3 = ?")
			values = append(values, t.Position_3)
		}
		if t.hasFieldChanged("machine_no") {
			setClauses = append(setClauses, "machine_no = ?")
			values = append(values, t.Machine_no)
		}
		if t.hasFieldChanged("production_lead_time") {
			setClauses = append(setClauses, "production_lead_time = ?")
			values = append(values, t.Production_lead_time)
		}
		if t.hasFieldChanged("variant_code") {
			setClauses = append(setClauses, "variant_code = ?")
			values = append(values, t.Variant_code)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "type = ?")
		values = append(values, t.Type)
		setClauses = append(setClauses, "no = ?")
		values = append(values, t.No)
		setClauses = append(setClauses, "bill_of_materials = ?")
		values = append(values, t.Bill_of_materials)
		setClauses = append(setClauses, "description = ?")
		values = append(values, t.Description)
		setClauses = append(setClauses, "unit_of_measure_code = ?")
		values = append(values, t.Unit_of_measure_code)
		setClauses = append(setClauses, "quantity_per = ?")
		values = append(values, t.Quantity_per)
		setClauses = append(setClauses, "position = ?")
		values = append(values, t.Position)
		setClauses = append(setClauses, "position_2 = ?")
		values = append(values, t.Position_2)
		setClauses = append(setClauses, "position_3 = ?")
		values = append(values, t.Position_3)
		setClauses = append(setClauses, "machine_no = ?")
		values = append(values, t.Machine_no)
		setClauses = append(setClauses, "production_lead_time = ?")
		values = append(values, t.Production_lead_time)
		setClauses = append(setClauses, "variant_code = ?")
		values = append(values, t.Variant_code)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["parent_item_no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Parent_item_no)
	}
	if old, ok := t.oldValues["line_no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Line_no)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND parent_item_no = ? AND line_no = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify BOM_Component: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *BOMComponent) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "parent_item_no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Parent_item_no.Equal(old)
		}
	case "line_no":
		if old, ok := oldValue.(int); ok {
			return t.Line_no != old
		}
		return true // Type mismatch, assume changed
	case "type":
		if old, ok := oldValue.(BOMComponentType); ok {
			return t.Type != old
		}
	case "no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.No.Equal(old)
		}
	case "bill_of_materials":
		if old, ok := oldValue.(bool); ok {
			return t.Bill_of_materials != old
		}
		return true // Type mismatch, assume changed
	case "description":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Description.Equal(old)
		}
	case "unit_of_measure_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Unit_of_measure_code.Equal(old)
		}
	case "quantity_per":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Quantity_per.Equal(old)
		}
	case "position":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Position.Equal(old)
		}
	case "position_2":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Position_2.Equal(old)
		}
	case "position_3":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Position_3.Equal(old)
		}
	case "machine_no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Machine_no.Equal(old)
		}
	case "production_lead_time":
		if old, ok := oldValue.(int); ok {
			return t.Production_lead_time != old
		}
		return true // Type mismatch, assume changed
	case "variant_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Variant_code.Equal(old)
		}
	}

	return false
}

