// FindSet opens a result set matching current filters
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *BOMComponent) FindSet() bool {
	// A temporary record, and a record in a transaction, reads all at once: its in-memory
	// database or the transaction has one connection, which an open result set would block for
	// the statements of the loop (Modify while looping; on PostgreSQL a query while the rows are
	// read breaks the connection — "unexpected Parse response")
	if _, inTx := t.db.(*sql.Tx); t.temp != nil || inTx {
		return t.FindSetBuffered()
	}
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	t.bufferedRecords = nil
	tableName := fmt.Sprintf("%s$%s", t.company, BOMComponentTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT parent_item_no, line_no, type, no, bill_of_materials, description, unit_of_measure_code, quantity_per, position, position_2, position_3, machine_no, production_lead_time, variant_code FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	query += t.forUpdate()

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for BOM_Component: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record: in the result set after FindSet() or FindSetBuffered(),
// else from the current record in the current key (after Get, Find, FindFirst, FindLast)
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (FindSetBuffered, or after Get/Find)
//   - Next(-3): Skip backward 3 records (FindSetBuffered, or after Get/Find)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *BOMComponent) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var parent_item_noNull sql.NullString
		var typeInt int
		var noNull sql.NullString
		var bill_of_materialsBool sql.NullBool
		var descriptionNull sql.NullString
		var unit_of_measure_codeNull sql.NullString
		var quantity_perNull sql.NullString
		var positionNull sql.NullString
		var position_2Null sql.NullString
		var position_3Null sql.NullString
		var machine_noNull sql.NullString
		var variant_codeNull sql.NullString

		err := t.currentRows.Scan(
			&parent_item_noNull,
			&t.Line_no,
			&typeInt,
			&noNull,
			&bill_of_materialsBool,
			&descriptionNull,
			&unit_of_measure_codeNull,
			&quantity_perNull,
			&positionNull,
			&position_2Null,
			&position_3Null,
			&machine_noNull,
			&t.Production_lead_time,
			&variant_codeNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan BOM_Component record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.Parent_item_no = types.NewCode(parent_item_noNull.String)
		t.Type = BOMComponentType(typeInt)
		t.No = types.NewCode(noNull.String)
		t.Bill_of_materials = bill_of_materialsBool.Bool
		t.Description = types.NewText(descriptionNull.String)
		t.Unit_of_measure_code = types.NewCode(unit_of_measure_codeNull.String)
		t.Quantity_per, _ = types.NewDecimalFromString(quantity_perNull.String)
		t.Position = types.NewCode(positionNull.String)
		t.Position_2 = types.NewCode(position_2Null.String)
		t.Position_3 = types.NewCode(position_3Null.String)
		t.Machine_no = types.NewCode(machine_noNull.String)
		t.Variant_code = types.NewCode(variant_codeNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No record set (after Get, Find, FindFirst, FindLast): the next record in the current key
	// and direction within the filters, one step at a time (classic NEXT after FIND); a step
	// that finds none leaves the record on the last one reached
	if step == 0 {
		return false
	}
	for i := 0; i != step; {
		if step > 0 {
			if !t.findInKey(">", false) {
				return false
			}
			i++
		} else {
			if !t.findInKey("<", true) {
				return false
			}
			i--
		}
	}
	return true
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *BOMComponent) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := fmt.Sprintf("%s$%s", t.company, BOMComponentTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT parent_item_no, line_no, type, no, bill_of_materials, description, unit_of_measure_code, quantity_per, position, position_2, position_3, machine_no, production_lead_time, variant_code FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for BOM_Component: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &BOMComponent{}
		record.db = t.db
		record.temp = t.temp
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var parent_item_noNull sql.NullString
		var typeInt int
		var noNull sql.NullString
		var bill_of_materialsBool sql.NullBool
		var descriptionNull sql.NullString
		var unit_of_measure_codeNull sql.NullString
		var quantity_perNull sql.NullString
		var positionNull sql.NullString
		var position_2Null sql.NullString
		var position_3Null sql.NullString
		var machine_noNull sql.NullString
		var variant_codeNull sql.NullString

		err := rows.Scan(
			&parent_item_noNull,
			&record.Line_no,
			&typeInt,
			&noNull,
			&bill_of_materialsBool,
			&descriptionNull,
			&unit_of_measure_codeNull,
			&quantity_perNull,
			&positionNull,
			&position_2Null,
			&position_3Null,
			&machine_noNull,
			&record.Production_lead_time,
			&variant_codeNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan BOM_Component record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.Parent_item_no = types.NewCode(parent_item_noNull.String)
		record.Type = BOMComponentType(typeInt)
		record.No = types.NewCode(noNull.String)
		record.Bill_of_materials = bill_of_materialsBool.Bool
		record.Description = types.NewText(descriptionNull.String)
		record.Unit_of_measure_code = types.NewCode(unit_of_measure_codeNull.String)
		record.Quantity_per, _ = types.NewDecimalFromString(quantity_perNull.String)
		record.Position = types.NewCode(positionNull.String)
		record.Position_2 = types.NewCode(position_2Null.String)
		record.Position_3 = types.NewCode(position_3Null.String)
		record.Machine_no = types.NewCode(machine_noNull.String)
		record.Variant_code = types.NewCode(variant_codeNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate BOM_Component records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

// copyFromBuffered copies field values from a buffered record to the current instance
func (t *BOMComponent) copyFromBuffered(record *BOMComponent) {
	t.Parent_item_no = record.Parent_item_no
	t.Line_no = record.Line_no
	t.Type = record.Type
	t.No = record.No
	t.Bill_of_materials = record.Bill_of_materials
	t.Description = record.Description
	t.Unit_of_measure_code = record.Unit_of_measure_code
	t.Quantity_per = record.Quantity_per
	t.Position = record.Position
	t.Position_2 = record.Position_2
	t.Position_3 = record.Position_3
	t.Machine_no = record.Machine_no
	t.Production_lead_time = record.Production_lead_time
	t.Bom_description = record.Bom_description
	t.Variant_code = record.Variant_code
	t.StoreOldValues()
}

